INSERT INTO `alibaba_matrix_800` (`listing_id`, `unique_sku_code`, `base_sku`, `base_product_name`, `angle_id`, `target_industry_angle`, `alibaba_product_title`, `alibaba_category`, `brand`, `place_of_origin`, `upper_material`, `outsole_material`, `toe_style`, `boot_height`, `colors`, `size_range`, `key_features`, `target_application`, `primary_keyword_1`, `primary_keyword_2`, `primary_keyword_3`, `longtail_keywords`, `moq_pairs`, `price_tier1_usd`, `price_tier2_usd`, `price_tier3_usd`, `pairs_per_carton`, `carton_dimensions`, `carton_gross_weight_kg`, `carton_cbm`, `port_of_loading`, `estimated_lead_time`, `tailored_html_description`, `image_1`, `image_2`, `image_3`, `image_4`, `image_5`, `image_6`) VALUES
('1001', 'AP-MX-01-V1', 'AP-MX-01', 'AP Max', '1', 'Oil & Gas Refinery', 'AP Boots AP Max Oil Gas Refinery Heavy Duty Safety Boots Waterproof Chemical Proof', 'Safety Footwear', 'AP Boots', 'Surabaya, Indonesia', 'High-Quality PVC / Synthetic Rubber Blend', 'Nitrile Rubber (Oil & Chemical Resistant)', 'Soft Toe', 'Ankle / Clog', 'Black, Yellow, Green, White', 'EU 38 - 43 (Selected variants EU 39 - 45)', 'Waterproof, Oil Resistant, Chemical Proof, Anti-Slip, Heavy Duty, Anti-Static', 'Oil & Gas Refinery, Petrochemical Plant, Offshore Drilling, Fuel Terminal', 'oil gas safety boots', 'refinery protective wellingtons', 'chemical resistant rubber boots', 'waterproof oil gas refinery boots, heavy duty safety wellingtons surabaya, chemical proof industrial boots, anti slip refinery footwear', 60, 9.77, 8.07, 6.8, 12, '60 x 40 x 40 cm', 12.0, 0.096, 'Surabaya, Indonesia', '7 - 14 Days', '<div class="product-description-container">\n<h2>AP Boots AP Max Oil Gas Refinery Heavy Duty Safety Boots Waterproof Chemical Proof</h2>\n<p><strong>Product Purpose & Overview:</strong> Engineered specifically for hazardous oil refineries, petrochemical processing plants, and offshore drilling platforms. Provides high-grade chemical resistance against hydrocarbons and oil slick hazards with high-traction slip resistance.</p>\n<h3>Key Features & Industry Benefits:</h3>\n<ul>\n    <li><strong>Application Focus:</strong> Specifically tailored for Oil & Gas Refinery, Petrochemical Plant, Offshore Drilling, Fuel Terminal.</li>\n    <li><strong>Material & Construction:</strong> Molded from High-Quality PVC / Synthetic Rubber Blend using seamless single-injection technology to guarantee 100% leak-proof reliability.</li>\n    <li><strong>Safety & Outsole:</strong> Features Nitrile Rubber (Oil & Chemical Resistant) with Waterproof, Oil Resistant, Chemical Proof, Anti-Slip, Heavy Duty, Anti-Static.</li>\n    <li><strong>Toe Protection:</strong> Equipped with Soft Toe for safety against physical hazards.</li>\n    <li><strong>Hygiene & Comfort:</strong> Ergonomic inner contour reduces foot fatigue during long work shifts. Easy to rinse and clean.</li>\n</ul>\n<h3>Technical Specifications:</h3>\n<table border="1" style="border-collapse: collapse; width: 100%;">\n    <tr><td><strong>Brand Name</strong></td><td>AP Boots (PT Waru Gunung Industry)</td></tr>\n    <tr><td><strong>Model Number / SKU</strong></td><td>AP-MX-01-V1 (Base: AP-MX-01)</td></tr>\n    <tr><td><strong>Place of Origin</strong></td><td>Surabaya, Indonesia</td></tr>\n    <tr><td><strong>Upper Material</strong></td><td>High-Quality PVC / Synthetic Rubber Blend</td></tr>\n    <tr><td><strong>Outsole Material</strong></td><td>Nitrile Rubber (Oil & Chemical Resistant)</td></tr>\n    <tr><td><strong>Toe Style</strong></td><td>Soft Toe</td></tr>\n    <tr><td><strong>Boot Height</strong></td><td>Ankle / Clog</td></tr>\n    <tr><td><strong>Available Colors</strong></td><td>Black, Yellow, Green, White</td></tr>\n    <tr><td><strong>Size Range</strong></td><td>EU 38 - 43 (Selected variants EU 39 - 45)</td></tr>\n    <tr><td><strong>Primary Application</strong></td><td>Oil & Gas Refinery, Petrochemical Plant, Offshore Drilling, Fuel Terminal</td></tr>\n</table>\n<h3>Packaging & Logistics Data:</h3>\n<ul>\n    <li><strong>MOQ (Minimum Order):</strong> 5 Master Cartons (60 Pairs)</li>\n    <li><strong>Packaging:</strong> 12 Pairs per Master Carton Box (60 x 40 x 40 cm)</li>\n    <li><strong>Gross Weight:</strong> Approx. 12.0 kg per carton box</li>\n    <li><strong>Volume:</strong> 0.096 CBM per carton box</li>\n    <li><strong>Port of Loading:</strong> Tanjung Perak, Surabaya / Tanjung Priok, Jakarta</li>\n    <li><strong>Lead Time:</strong> 7 - 14 Business Days</li>\n</ul>\n</div>', 'https://p16-images-sign-sg.tokopedia-static.net/tos-alisg-i-aphluv4xwc-sg/3d343f9c5f094dfb8d690504b81c0cd7~tplv-aphluv4xwc-white-pad-v1:1600:1600.jpeg', 'https://p16-images-sign-sg.tokopedia-static.net/tos-alisg-i-aphluv4xwc-sg/3